import fs from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';
const base=path.resolve('scripts/qa/output/carson-home-team-access-20261003-PROD'),out=path.join(base,(await fs.readdir(base)).sort().at(-1)),s=JSON.parse(await fs.readFile(path.join(out,'summary.json'),'utf8')),a=s.actors.find(a=>a.label==='nonadmin-analyst'),browser=await chromium.launch({headless:true});try{const c=await browser.newContext({storageState:path.join(s.privateEvidence,a.label+'-storage.json'),viewport:{width:1440,height:1050}}),p=await c.newPage();p.setDefaultTimeout(8000);await p.goto('https://app.reconiq.example/'+a.slug+'/workspace?page=dashboard',{waitUntil:'domcontentloaded'});await p.getByRole('button',{name:'My scope',exact:true}).waitFor({timeout:35000});const close=p.locator('.driver-popover-close-btn');if(await close.isVisible().catch(()=>false))await close.click();await p.getByRole('button',{name:'Team scope',exact:true}).click();let settled=false;try{await p.getByRole('alert').filter({hasText:'Workspace dashboard unavailable'}).waitFor({timeout:45000});settled=true;}catch{}const text=await p.locator('body').innerText();const proof={actor:a.label,url:p.url(),at:new Date().toISOString(),settled,alerts:await p.getByRole('alert').allTextContents(),text};await fs.writeFile(path.join(out,'team-settled-proof.json'),JSON.stringify(proof,null,2));await p.screenshot({path:path.join(out,'nonadmin-analyst-team-settled.png'),fullPage:true});console.log(JSON.stringify({out,settled,alerts:proof.alerts,tail:text.slice(-600)}));}finally{await browser.close();}
